/**
 * Look up the manufacturer for a MAC or OUI, longest prefix first.
 *
 * @param hex uppercase hex with no separators: a full 12 character MAC where one is known,
 *            or just the 6 character OUI. A 28 or 36 bit assignment can only be matched
 *            when enough of the address is supplied.
 * @returns the manufacturer, or undefined if the prefix is not one we carry
 */
export function lookupOui(hex: string): string | undefined {
	const key = hex.replace(/[^0-9a-fA-F]/g, '').toUpperCase()
	for (const length of [9, 7, 6]) {
		if (key.length < length) continue
		const index = ouiPrefixes[key.slice(0, length)]
		if (index !== undefined) return ouiNames[index]
	}
	return undefined
}
